SM_TEST(o_cracha_de_quem_ja_esta_na_lista) {
    /* caso comum: bruno e o segundo da lista e sai com o cracha 207 */
    char convidados[3][20] = {"ana", "bruno", "carla"};
    int numeros[3] = {104, 207, 311};

    FILE *e = fopen("sm_entrada_1.tmp", "w");
    fprintf(e, "bruno\n");
    fclose(e);
    freopen("sm_entrada_1.tmp", "r", stdin);

    char cracha[60] = "(nada escrito)";
    int numero = oCrachaDoCongresso(convidados, numeros, 3, cracha);
    checa_int("o numero devolvido do cracha", numero, 207,
              "bruno e o indice 1, e o numero vem da lista de numeros na mesma posicao");
    checa_str("o texto do cracha", cracha, "207 BRUNO",
              "o texto junta o numero com o nome gritado em maiusculas");
}

