#include <stdio.h>
#include <string.h>
#include <ctype.h>

void paraMaiusculas(char s[]) {
    for (int i = 0; s[i] != '\0'; i++) {
        s[i] = toupper(s[i]);
    }
}

int oIndiceDoConvidado(char convidados[][20], int n, char nome[]) {
    for (int i = 0; i < n; i++) {
        if (strcmp(convidados[i], nome) == 0) {
            return i;
        }
    }
    return -1;
}

int oCrachaDoCongresso(char convidados[][20], int numeros[], int n, char cracha[]) {
    char nome[50] = "";
    scanf("%49s", nome);

    if (strlen(nome) >= 20) {
        snprintf(cracha, 60, "nome grande demais");
        return -1;
    }

    char emMaiusculas[20] = "";
    strncpy(emMaiusculas, nome, sizeof emMaiusculas);
    emMaiusculas[sizeof emMaiusculas - 1] = '\0';
    paraMaiusculas(emMaiusculas);

    int indice = oIndiceDoConvidado(convidados, n, nome);
    if (indice < 0) {
        snprintf(cracha, 60, "sem inscricao: %s", emMaiusculas);
        return -1;
    }

    snprintf(cracha, 60, "%d %s", numeros[indice], emMaiusculas);
    return numeros[indice];
}
